  EXPECT_EQ(buffer, fmt::format("{0:e}", 392.65));
  safe_sprintf(buffer, "%E", 392.65);
  EXPECT_EQ(buffer, fmt::format("{0:E}", 392.65));
  EXPECT_EQ("+0000392.6", fmt::format("{0:+010.4g}", 392.65));
  safe_sprintf(buffer, "%a", -42.0);
  EXPECT_EQ(buffer, fmt::format("{:a}", -42.0));
